<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { api,useLoad,PageHeader,Feedback,EmptyState,StatusBadge,money,time,can,type Page,type Order } from '@tradeflow/ui'
import { pathNo } from '../state'
const page=ref(1),lookup=ref(''),status=ref('');const load=useLoad<Page<Order>>(s=>api(`/orders?page=${page.value}&pageSize=12&status=${encodeURIComponent(status.value)}&orderNo=${encodeURIComponent(lookup.value)}`,{signal:s}));onMounted(()=>{if(can('ORDERS'))void load.reload()});async function change(n:number){page.value=n;await load.reload()}
</script>
<template><section><PageHeader title="我的订单" description="从受理到收货，查看每一笔真实交易的进度。"><template #actions><RouterLink class="button" to="/trade-groups">分商家交易</RouterLink><button :disabled="!can('ORDERS')" @click="load.reload()">刷新订单</button></template></PageHeader><form class="lookup" @submit.prevent="change(1)"><label for="order-state">订单状态</label><select id="order-state" v-model="status"><option value="">全部</option><option value="PENDING_PAYMENT">待支付</option><option value="PAID">待发货</option><option value="SHIPPED">待收货</option><option value="COMPLETED">已完成</option><option value="CLOSED">已关闭</option></select><button type="submit">筛选订单</button><label for="order-lookup">按订单号查看</label><input id="order-lookup" v-model.trim="lookup" placeholder="输入完整订单号"/><RouterLink v-if="lookup" class="button secondary" :to="`/orders/${pathNo(lookup)}`">查看订单</RouterLink></form><Feedback :error="load.error.value" :loading="load.loading.value"/><EmptyState v-if="load.data.value && !load.data.value.items.length" title="还没有订单" description="选购商品后，你的交易记录会出现在这里。"><RouterLink to="/" class="button primary">浏览商品</RouterLink></EmptyState><article v-for="order in load.data.value?.items" :key="order.orderNo" class="panel order-card"><div class="row spread"><div><p class="small muted mono">{{order.orderNo}}</p><p class="small muted">{{time(order.createdAt)}}</p></div><StatusBadge :status="order.status"/></div><div class="row spread"><div><h2>{{order.items[0]?.productName || '订单商品'}}</h2><p class="muted">{{order.items.length}} 种规格 · {{order.items.reduce((s,i)=>s+i.quantity,0)}} 件</p></div><strong class="price">{{money(order.amountCents)}}</strong></div><RouterLink :to="`/orders/${pathNo(order.orderNo)}`" class="button secondary">查看进度与操作</RouterLink></article><div v-if="load.data.value" class="pagination"><button :disabled="page<=1" @click="change(page-1)">上一页</button><span>第 {{page}} 页 · 共 {{load.data.value.total}} 单</span><button :disabled="page*12>=load.data.value.total" @click="change(page+1)">下一页</button></div></section></template>
